// Ambil seluruh data dari node Mock Bank Feed
const mutations = $('Mock Bank Feed').all().map(item => item.json);

let totalIn = 0;
let totalOut = 0;
let adminFeesCount = 0;
let invoiceCount = 0;

for (const m of mutations) {
  const amt = Number(m.amount || 0);
  if (m.mutation_type === 'CR') {
    totalIn += amt;
  } else {
    totalOut += amt;
  }

  const desc = (m.description || '').toUpperCase();
  if (desc.includes('BIAYA ADM') || desc.includes('BIAYA TRANSFER')) {
    adminFeesCount++;
  }
  if (desc.includes('INV-')) {
    invoiceCount++;
  }
}

// Format Rupiah
const formatRupiah = (num) => 'Rp ' + num.toLocaleString('id-ID');

return [{
  json: {
    total_mutasi: mutations.length,
    total_masuk: formatRupiah(totalIn),
    total_keluar: formatRupiah(totalOut),
    biaya_admin: adminFeesCount,
    invoice_terdeteksi: invoiceCount,
    batch_time: new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB',
    batch_date: new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })
  }
}];
